    "codeExample": "function inorderTraversal(root) {\n  const res = [], stack = [];\n  let curr = root;\n  while (curr || stack.length) {\n    while (curr) { stack.push(curr); curr = curr.left; }\n    curr = stack.pop();\n    res.push(curr.val);\n    curr = curr.right;\n  }\n  return res;\n}",
