    "codeExample": "function generateMatrix(n) {\n  const mat = Array.from({ length: n }, () => new Array(n));\n  let top = 0, bottom = n - 1, left = 0, right = n - 1, val = 1;\n  while (top <= bottom && left <= right) {\n    for (let c = left; c <= right; c++) mat[top][c] = val++;\n    top++;\n    for (let r = top; r <= bottom; r++) mat[r][right] = val++;\n    right--;\n    for (let c = right; c >= left; c--) mat[bottom][c] = val++;\n    bottom--;\n    for (let r = bottom; r >= top; r--) mat[r][left] = val++;\n    left++;\n  }\n  return mat;\n}",
